package com.dshgo.shellpol;
import de.robv.android.xposed.XC_MethodHook;import de.robv.android.xposed.XposedBridge;import org.luckypray.dexkit.DexKitBridge;import org.luckypray.dexkit.query.FindMethod;import org.luckypray.dexkit.query.matchers.MethodMatcher;import org.luckypray.dexkit.result.MethodData;import java.lang.reflect.Method;import java.util.Arrays;
/** Extends only the Android Shell tool budget; task cancellation and owner state remain intact. */
final class PhoneBudgetRelax{private PhoneBudgetRelax(){}static void install(DexKitBridge b,ClassLoader l)throws Exception{MethodData s=null;for(MethodData m:b.findMethod(new FindMethod().matcher(new MethodMatcher().usingEqStrings("android_shell")))){if(!"long".equals(m.getReturnTypeName())||!Arrays.asList("java.lang.String").equals(m.getParamTypeNames()))continue;if(s!=null)throw new IllegalStateException("ambiguous Android Shell budget method");s=m;}if(s==null)throw new IllegalStateException("Android Shell budget method missing");Method t=s.getMethodInstance(l);XposedBridge.hookMethod(t,new XC_MethodHook(){@Override protected void beforeHookedMethod(MethodHookParam p){if(p.args!=null&&p.args.length==1&&"android_shell".equals(p.args[0]))p.setResult(Long.MAX_VALUE/2000000L);}});XposedBridge.log(HookEntry.TAG+": budget_relax installed "+s.getDescriptor());}}
